{"description":"验收图片解码尺寸及任务映射","command":"python3 - <<'PY'
import json, pathlib, subprocess
m=json.load(open('manifest.json')); s=json.load(open('submission.json')); r=json.load(open('media.json')); report=[]
assert len(m['items'])==len(s['items'])==len(r['runs'])==11
for n,(a,b,c) in enumerate(zip(m['items'],s['items'],r['runs']),1):
 errors=[]
 if not (a['request_id']==b['request_id']==c.get('request_id') and b['run_id']==c.get('run_id')): errors.append('request/run mismatch')
 if c.get('status')!='succeeded' or len(c.get('images',[]))!=1: errors.append('status or media count')
 prm=c.get('parameters',{}); original=pathlib.Path(a['parameter_files']['positive_prompt']).read_bytes().decode('utf-8')
 if prm.get('positive_prompt')!=original: errors.append('prompt differs')
 for k,v in a['request']['parameters'].items():
  if prm.get(k)!=v: errors.append(f'{k} differs')
 im=c['images'][0]; path=im['file_path']
 p=subprocess.run(['sips','-g','pixelWidth','-g','pixelHeight',path],capture_output=True,text=True)
 if p.returncode or 'pixelWidth: 512' not in p.stdout or 'pixelHeight: 512' not in p.stdout: errors.append('image read/dimensions: '+p.stdout+p.stderr)
 # Decode the entire file via ImageIO, not just header properties.
 q=subprocess.run(['sips','-s','format','png',path,'--out','/dev/null'],capture_output=True,text=True)
 if q.returncode: errors.append('decode: '+q.stderr)
 report.append({'index':n,'seed':424241+n,'run_id':c['run_id'],'request_id':c['request_id'],'media_id':im['media_id'],'path':path,'errors':errors})
print(json.dumps(report,ensure_ascii=False,indent=2))
pathlib.Path('acceptance.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
if any(x['errors'] for x in report): raise SystemExit(1)
PY"}

